export interface CropRegion {
  x: number;
  y: number;
  width: number;
  height: number;
}

export type AspectRatioPreset = "free" | "1:1" | "4:3" | "16:9" | "3:2" | "9:16";
export type OutputFormat = "image/png" | "image/jpeg" | "image/webp";

export interface CropperConfig {
  defaultAspectRatio?: AspectRatioPreset;
  outputFormat?: OutputFormat;
  quality?: number;
  /** Minimum crop dimension in image px. Default 20. */
  minSize?: number;
  /** Show rule-of-thirds grid. Default true. */
  showGrid?: boolean;
}

export interface ImageSize {
  width: number;
  height: number;
}

export interface CanvasTransform {
  scale: number;
  offsetX: number;
  offsetY: number;
}

export interface CropperContextValue {
  src: string;
  imageSize: ImageSize | null;
  region: CropRegion | null;
  aspectRatioPreset: AspectRatioPreset;
  aspectRatio: number | null;
  config: CropperConfig;
  setImageSize: (size: ImageSize) => void;
  setRegion: (region: CropRegion) => void;
  setAspectRatioPreset: (preset: AspectRatioPreset) => void;
  crop: () => Promise<Blob>;
  reset: () => void;
}

import type { CropRegion, CanvasTransform, AspectRatioPreset } from "./types";

export type HandleId = "n" | "ne" | "e" | "se" | "s" | "sw" | "w" | "nw" | "move";

// ─── Transform ────────────────────────────────────────────────────────────────

export function computeTransform(
  canvasW: number,
  canvasH: number,
  imgW: number,
  imgH: number,
): CanvasTransform {
  const scale = Math.min(canvasW / imgW, canvasH / imgH);
  return {
    scale,
    offsetX: (canvasW - imgW * scale) / 2,
    offsetY: (canvasH - imgH * scale) / 2,
  };
}

// ─── Aspect ratio ─────────────────────────────────────────────────────────────

export function parseAspectRatio(preset: AspectRatioPreset): number | null {
  const map: Record<AspectRatioPreset, number | null> = {
    free: null,
    "1:1": 1,
    "4:3": 4 / 3,
    "16:9": 16 / 9,
    "3:2": 3 / 2,
    "9:16": 9 / 16,
  };
  return map[preset];
}

// ─── Default region ───────────────────────────────────────────────────────────

export function defaultRegion(
  imgW: number,
  imgH: number,
  aspectRatio: number | null,
): CropRegion {
  const pad = 0.1;
  let w = imgW * (1 - pad * 2);
  let h = imgH * (1 - pad * 2);
  if (aspectRatio !== null) {
    if (w / h > aspectRatio) w = h * aspectRatio;
    else h = w / aspectRatio;
  }
  return { x: (imgW - w) / 2, y: (imgH - h) / 2, width: w, height: h };
}

// ─── Handle drag ──────────────────────────────────────────────────────────────

function clamp(v: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, v));
}

export function applyHandleDrag(
  region: CropRegion,
  handle: HandleId,
  dx: number,        // delta in image px
  dy: number,
  imgW: number,
  imgH: number,
  aspectRatio: number | null,
  minSize = 20,
): CropRegion {
  if (handle === "move") {
    return {
      ...region,
      x: clamp(region.x + dx, 0, imgW - region.width),
      y: clamp(region.y + dy, 0, imgH - region.height),
    };
  }

  const isN = handle.includes("n");
  const isS = handle.includes("s");
  const isW = handle.includes("w");
  const isE = handle.includes("e");

  let left = region.x;
  let top = region.y;
  let right = region.x + region.width;
  let bottom = region.y + region.height;

  if (isN) top = clamp(top + dy, 0, bottom - minSize);
  if (isS) bottom = clamp(bottom + dy, top + minSize, imgH);
  if (isW) left = clamp(left + dx, 0, right - minSize);
  if (isE) right = clamp(right + dx, left + minSize, imgW);

  let width = right - left;
  let height = bottom - top;

  if (aspectRatio !== null) {
    const pureH = (isE || isW) && !isN && !isS;
    const pureV = (isN || isS) && !isE && !isW;

    if (pureH) {
      height = width / aspectRatio;
      const cy = (top + bottom) / 2;
      top = cy - height / 2;
      bottom = cy + height / 2;
    } else if (pureV) {
      width = height * aspectRatio;
      const cx = (left + right) / 2;
      left = cx - width / 2;
      right = cx + width / 2;
    } else {
      // Corner: width-primary
      height = width / aspectRatio;
      if (isN) top = bottom - height;
      else bottom = top + height;
    }

    // Re-clamp after AR adjustment
    if (left < 0) { right -= left; left = 0; }
    if (top < 0) { bottom -= top; top = 0; }
    if (right > imgW) { left -= right - imgW; right = imgW; }
    if (bottom > imgH) { top -= bottom - imgH; bottom = imgH; }
  }

  return { x: left, y: top, width: right - left, height: bottom - top };
}

// ─── Hit test ─────────────────────────────────────────────────────────────────

interface CropBox { x: number; y: number; w: number; h: number }

export function getHandlePositions(cb: CropBox) {
  return [
    { id: "nw" as HandleId, x: cb.x,            y: cb.y            },
    { id: "n"  as HandleId, x: cb.x + cb.w / 2, y: cb.y            },
    { id: "ne" as HandleId, x: cb.x + cb.w,     y: cb.y            },
    { id: "e"  as HandleId, x: cb.x + cb.w,     y: cb.y + cb.h / 2 },
    { id: "se" as HandleId, x: cb.x + cb.w,     y: cb.y + cb.h     },
    { id: "s"  as HandleId, x: cb.x + cb.w / 2, y: cb.y + cb.h     },
    { id: "sw" as HandleId, x: cb.x,            y: cb.y + cb.h     },
    { id: "w"  as HandleId, x: cb.x,            y: cb.y + cb.h / 2 },
  ];
}

export function hitTest(
  px: number,
  py: number,
  cb: CropBox,
  hitRadius = 8,
): HandleId | null {
  for (const { id, x, y } of getHandlePositions(cb)) {
    if (Math.abs(px - x) <= hitRadius && Math.abs(py - y) <= hitRadius) return id;
  }
  if (px >= cb.x && px <= cb.x + cb.w && py >= cb.y && py <= cb.y + cb.h) {
    return "move";
  }
  return null;
}

// ─── Export ───────────────────────────────────────────────────────────────────

export async function generateCrop(
  src: string,
  region: CropRegion,
  format: OutputFormat = "image/png",
  quality = 0.92,
): Promise<Blob> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      const c = document.createElement("canvas");
      c.width = Math.round(region.width);
      c.height = Math.round(region.height);
      c.getContext("2d")!.drawImage(
        img,
        Math.round(region.x), Math.round(region.y),
        Math.round(region.width), Math.round(region.height),
        0, 0, c.width, c.height,
      );
      c.toBlob(
        (b) => (b ? resolve(b) : reject(new Error("toBlob failed"))),
        format,
        quality,
      );
    };
    img.onerror = reject;
    img.src = src;
  });
}

type OutputFormat = "image/png" | "image/jpeg" | "image/webp";

"use client";

import * as React from "react";
import type { CropperContextValue } from "./types";

export const CropperCtx = React.createContext<CropperContextValue | null>(null);

export function useCropper(): CropperContextValue {
  const ctx = React.useContext(CropperCtx);
  if (!ctx) throw new Error("useCropper must be used inside CropperRoot");
  return ctx;
}

"use client";

import * as React from "react";
import { CropperCtx } from "./cropper-context";
import { CropperCanvas } from "./cropper-canvas";
import { CropperToolbar } from "./cropper-toolbar";
import { CropperPreview } from "./cropper-preview";
import { defaultRegion, parseAspectRatio, generateCrop } from "./crop-engine";
import type {
  CropperConfig, CropperContextValue, CropRegion, ImageSize, AspectRatioPreset,
} from "./types";
import { cn } from "@/lib/utils";

export interface CropperRootProps {
  /** Image URL. Must have CORS headers if the origin differs. */
  src: string;
  config?: CropperConfig;
  /** Called after crop() resolves. */
  onCrop?: (blob: Blob) => void;
  /** Replace the default layout entirely. */
  children?: React.ReactNode;
  className?: string;
}

export function CropperRoot({
  src,
  config = {},
  onCrop,
  children,
  className,
}: CropperRootProps) {
  const [imageSize, setImageSizeState] = React.useState<ImageSize | null>(null);
  const [region, setRegion] = React.useState<CropRegion | null>(null);
  const [aspectRatioPreset, setPresetState] = React.useState<AspectRatioPreset>(
    config.defaultAspectRatio ?? "free",
  );

  const aspectRatio = parseAspectRatio(aspectRatioPreset);

  function setImageSize(size: ImageSize) {
    setImageSizeState(size);
    setRegion(defaultRegion(size.width, size.height, aspectRatio));
  }

  function setAspectRatioPreset(preset: AspectRatioPreset) {
    setPresetState(preset);
    if (!imageSize) return;
    setRegion(defaultRegion(imageSize.width, imageSize.height, parseAspectRatio(preset)));
  }

  async function crop(): Promise<Blob> {
    if (!region) throw new Error("No crop region");
    const blob = await generateCrop(
      src, region,
      config.outputFormat ?? "image/png",
      config.quality ?? 0.92,
    );
    onCrop?.(blob);
    return blob;
  }

  function reset() {
    if (!imageSize) return;
    setRegion(defaultRegion(imageSize.width, imageSize.height, aspectRatio));
  }

  const ctx: CropperContextValue = {
    src, imageSize, region,
    aspectRatioPreset, aspectRatio, config,
    setImageSize, setRegion, setAspectRatioPreset, crop, reset,
  };

  return (
    <CropperCtx.Provider value={ctx}>
      {children ?? (
        <div className={cn("flex flex-col gap-3", className)}>
          <CropperToolbar />
          <div className="flex gap-4 items-start">
            <CropperCanvas className="flex-1" />
            <CropperPreview />
          </div>
        </div>
      )}
    </CropperCtx.Provider>
  );
}

CropperRoot.displayName = "CropperRoot";

"use client";

import * as React from "react";
import { useCropper } from "./cropper-context";
import {
  computeTransform,
  applyHandleDrag,
  getHandlePositions,
  hitTest,
  type HandleId,
} from "./crop-engine";
import type { CropRegion, CanvasTransform } from "./types";
import { cn } from "@/lib/utils";

const HANDLE_SIZE = 8;

const CURSOR_MAP: Record<HandleId, string> = {
  nw: "nw-resize",
  n: "n-resize",
  ne: "ne-resize",
  e: "e-resize",
  se: "se-resize",
  s: "s-resize",
  sw: "sw-resize",
  w: "w-resize",
  move: "move",
};

interface DragState {
  handle: HandleId;
  startX: number;
  startY: number;
  startRegion: CropRegion;
}

export interface CropperCanvasProps {
  className?: string;
}

export function CropperCanvas({ className }: CropperCanvasProps) {
  const {
    src,
    imageSize,
    region,
    aspectRatio,
    config,
    setImageSize,
    setRegion,
  } = useCropper();

  const containerRef = React.useRef<HTMLDivElement>(null);
  const [containerSize, setContainerSize] = React.useState<{
    w: number;
    h: number;
  } | null>(null);
  const dragRef = React.useRef<DragState | null>(null);
  const [cursor, setCursor] = React.useState("default");

  // Unique mask ID — avoid collisions with multiple instances
  const maskId = React.useId().replace(/:/g, "m");

  React.useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const ro = new ResizeObserver((entries) => {
      const { width, height } = entries[0].contentRect;
      setContainerSize({ w: width, h: height });
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const transform: CanvasTransform | null =
    containerSize && imageSize
      ? computeTransform(
          containerSize.w,
          containerSize.h,
          imageSize.width,
          imageSize.height,
        )
      : null;

  const cropBox =
    region && transform
      ? {
          x: transform.offsetX + region.x * transform.scale,
          y: transform.offsetY + region.y * transform.scale,
          w: region.width * transform.scale,
          h: region.height * transform.scale,
        }
      : null;

  const imgStyle: React.CSSProperties = transform
    ? {
        position: "absolute",
        left: transform.offsetX,
        top: transform.offsetY,
        width: imageSize!.width * transform.scale,
        height: imageSize!.height * transform.scale,
        pointerEvents: "none",
        userSelect: "none",
      }
    : { position: "absolute", opacity: 0 };

  // ── Pointer handlers on SVG ────────────────────────────────────────────────

  function onSvgPointerDown(e: React.PointerEvent<SVGSVGElement>) {
    if (!cropBox || !region) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const px = e.clientX - rect.left;
    const py = e.clientY - rect.top;
    const handle = hitTest(px, py, cropBox);
    if (!handle) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    dragRef.current = {
      handle,
      startX: e.clientX,
      startY: e.clientY,
      startRegion: { ...region },
    };
    setCursor(CURSOR_MAP[handle]);
    e.preventDefault();
  }

  function onSvgPointerMove(e: React.PointerEvent<SVGSVGElement>) {
    if (dragRef.current) {
      if (!imageSize || !transform) return;
      const { handle, startX, startY, startRegion } = dragRef.current;
      const dxImg = (e.clientX - startX) / transform.scale;
      const dyImg = (e.clientY - startY) / transform.scale;
      setRegion(
        applyHandleDrag(
          startRegion,
          handle,
          dxImg,
          dyImg,
          imageSize.width,
          imageSize.height,
          aspectRatio,
          config.minSize,
        ),
      );
    } else if (cropBox) {
      const rect = e.currentTarget.getBoundingClientRect();
      const handle = hitTest(
        e.clientX - rect.left,
        e.clientY - rect.top,
        cropBox,
      );
      setCursor(handle ? CURSOR_MAP[handle] : "default");
    }
  }

  function onSvgPointerUp() {
    dragRef.current = null;
    setCursor("default");
  }

  const showGrid = config.showGrid !== false;

  return (
    <div
      ref={containerRef}
      className={cn(
        "relative overflow-hidden rounded-lg  bg-background select-none",
        "h-[420px]",
        className,
      )}
    >
      <img
        src={src}
        alt=""
        style={imgStyle}
        draggable={false}
        crossOrigin="anonymous"
        onLoad={(e) => {
          const img = e.currentTarget;
          setImageSize({ width: img.naturalWidth, height: img.naturalHeight });
        }}
      />

      {cropBox && (
        <svg
          className="absolute inset-0 w-full h-full"
          style={{ cursor }}
          onPointerDown={onSvgPointerDown}
          onPointerMove={onSvgPointerMove}
          onPointerUp={onSvgPointerUp}
          onPointerCancel={onSvgPointerUp}
        >
          <defs>
            <mask id={maskId}>
              <rect width="100%" height="100%" fill="white" />
              <rect
                x={cropBox.x}
                y={cropBox.y}
                width={cropBox.w}
                height={cropBox.h}
                fill="black"
              />
            </mask>
          </defs>

          {/* Shade */}
          <rect
            width="100%"
            height="100%"
            fill="rgba(0,0,0,0.55)"
            mask={`url(#${maskId})`}
          />

          {/* Rule-of-thirds */}
          {showGrid && (
            <g stroke="rgba(255,255,255,0.18)" strokeWidth={0.5}>
              {[1 / 3, 2 / 3].map((t) => (
                <React.Fragment key={t}>
                  <line
                    x1={cropBox.x + cropBox.w * t}
                    y1={cropBox.y}
                    x2={cropBox.x + cropBox.w * t}
                    y2={cropBox.y + cropBox.h}
                    className="stroke-white"
                  />
                  <line
                    x1={cropBox.x}
                    y1={cropBox.y + cropBox.h * t}
                    x2={cropBox.x + cropBox.w}
                    y2={cropBox.y + cropBox.h * t}
                    className="stroke-white"
                  />
                </React.Fragment>
              ))}
            </g>
          )}

          {/* Crop border */}
          <rect
            x={cropBox.x}
            y={cropBox.y}
            width={cropBox.w}
            height={cropBox.h}
            fill="none"
            stroke="var(--color-primary)"
            strokeWidth={1.5}
          />

          {/* Handles */}
          {getHandlePositions(cropBox).map(({ id, x, y }) => (
            <rect
              key={id}
              x={x - HANDLE_SIZE / 2}
              y={y - HANDLE_SIZE / 2}
              width={HANDLE_SIZE}
              height={HANDLE_SIZE}
              fill="white"
              // stroke="rgba(0,0,0,0.25)"
              className="stroke-primary fill-primary"
              strokeWidth={1}
              rx={1.5}
              style={{ pointerEvents: "none" }}
            />
          ))}
        </svg>
      )}

      {!imageSize && (
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-[11px] font-mono text-muted-foreground/40">
            Loading…
          </span>
        </div>
      )}
    </div>
  );
}

CropperCanvas.displayName = "CropperCanvas";

"use client";

import * as React from "react";
import { useCropper } from "./cropper-context";
import { IconCrop, IconRefresh } from "@tabler/icons-react";
import type { AspectRatioPreset } from "./types";
import { cn } from "@/lib/utils";
import {Button} from "@/components/ui/button"
const AR_PRESETS: AspectRatioPreset[] = ["free", "1:1", "4:3", "16:9", "3:2", "9:16"];
const AR_LABELS: Record<AspectRatioPreset, string> = {
  free: "Free",
  "1:1": "1:1",
  "4:3": "4:3",
  "16:9": "16:9",
  "3:2": "3:2",
  "9:16": "9:16",
};

export interface CropperToolbarProps {
  /** Override for the Crop button's action — useful when you need custom blob handling. */
  onCrop?: (blob: Blob) => void;
  className?: string;
}

export function CropperToolbar({ onCrop, className }: CropperToolbarProps) {
  const { aspectRatioPreset, setAspectRatioPreset, crop, reset, region } = useCropper();
  const [busy, setBusy] = React.useState(false);

  async function handleCrop() {
    setBusy(true);
    try {
      const blob = await crop();
      onCrop?.(blob);
    } finally {
      setBusy(false);
    }
  }

  const dims = region
    ? `${Math.round(region.width)} × ${Math.round(region.height)}`
    : null;

  return (
    <div className={cn("flex items-center gap-2 flex-wrap", className)}>
      {/* AR presets */}
      <div className="flex items-center gap-1 p-1 rounded-lg bg-background">
        {AR_PRESETS.map((preset) => (
          <Button
            key={preset}
            type="button"
            onClick={() => setAspectRatioPreset(preset)}
            variant={aspectRatioPreset === preset ? 'default' : 'secondary'}
          >
            {AR_LABELS[preset]}
          </Button>
        ))}
      </div>

      {dims && (
        <span className="text-[11px] font-mono text-muted-foreground/50">{dims}px</span>
      )}

      <div className="flex-1" />

      <Button
        type="button"
        onClick={reset}
        variant={'outline'}
      >
        <IconRefresh size={13} strokeWidth={1.8} />
        Reset
      </Button>

      <Button
        type="button"
        onClick={handleCrop}
        disabled={busy || !region}
      >
        <IconCrop size={13} strokeWidth={1.8} />
        {busy ? "Processing…" : "Crop"}
      </Button>
    </div>
  );
}

CropperToolbar.displayName = "CropperToolbar";

"use client";

import * as React from "react";
import { useCropper } from "./cropper-context";
import { cn } from "@/lib/utils";

export interface CropperPreviewProps {
  maxSize?: number;
  className?: string;
}

export function CropperPreview({ maxSize = 140, className }: CropperPreviewProps) {
  const { src, region } = useCropper();
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const imgRef = React.useRef<HTMLImageElement | null>(null);

  // Load image once, re-draw when region changes
  React.useEffect(() => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => { imgRef.current = img; draw(); };
    img.src = src;
  }, [src]); // eslint-disable-line

  function draw() {
    const canvas = canvasRef.current;
    const img = imgRef.current;
    if (!canvas || !img || !region) return;
    const { x, y, width, height } = region;
    canvas.width = Math.round(width);
    canvas.height = Math.round(height);
    canvas
      .getContext("2d")!
      .drawImage(img, Math.round(x), Math.round(y), Math.round(width), Math.round(height),
        0, 0, canvas.width, canvas.height);
  }

  React.useEffect(() => { draw(); }, [region]); // eslint-disable-line

  if (!region) return null;

  const aspect = region.width / region.height;
  const displayW = aspect >= 1 ? maxSize : Math.round(maxSize * aspect);
  const displayH = aspect >= 1 ? Math.round(maxSize / aspect) : maxSize;

  return (
    <div className={cn("flex flex-col gap-2 shrink-0", className)}>
      <span className="text-[10px] font-mono uppercase tracking-wider text-muted-foreground/50">
        Preview
      </span>
      <div
        className="rounded-lg overflow-hidden border border-border/60 bg-background"
        style={{ width: displayW, height: displayH }}
      >
        <canvas ref={canvasRef} style={{ width: "100%", height: "100%", display: "block" }} />
      </div>
      <span className="text-[10px] font-mono text-muted-foreground/40">
        {Math.round(region.width)} × {Math.round(region.height)}px
      </span>
    </div>
  );
}

CropperPreview.displayName = "CropperPreview";

export { CropperRoot } from "./cropper-root";
export { CropperCanvas } from "./cropper-canvas";
export { CropperToolbar } from "./cropper-toolbar";
export { CropperPreview } from "./cropper-preview";
export { useCropper } from "./cropper-context";
export type {
  CropRegion,
  AspectRatioPreset,
  OutputFormat,
  CropperConfig,
  // CropperRootProps,
} from "./types";
